    /**
     * Checks all input fields of the dialog and only enables the save button if every field
     * contains a valid value. Invalid fields are marked with a short description of the problem.
     */
    private static void validateInputs(MainActivity callingActivity, Button positiveButton,
                                       EditText labelInput, EditText secretInput,
                                       EditText periodInput, EditText digitsInput) {
        boolean valid = true;

        if (TextUtils.isEmpty(labelInput.getText())) {
            valid = false;
            setError(labelInput, callingActivity.getString(R.string.error_empty_input));
        } else {
            setError(labelInput, null);
        }

        if (TextUtils.isEmpty(secretInput.getText())) {
            valid = false;
            setError(secretInput, callingActivity.getString(R.string.error_empty_input));
        } else {
            setError(secretInput, null);
        }

        if (isValidNumber(periodInput, MAX_PERIOD)) {
            setError(periodInput, null);
        } else {
            valid = false;
            setError(periodInput, callingActivity.getString(R.string.error_invalid_period, MAX_PERIOD));
        }

        if (isValidNumber(digitsInput, MAX_DIGITS)) {
            setError(digitsInput, null);
        } else {
            valid = false;
            setError(digitsInput, callingActivity.getString(R.string.error_invalid_digits, MAX_DIGITS));
        }

        positiveButton.setEnabled(valid);
    }

    /** Only updates the error of an input field if it actually changed to avoid flickering. */
    private static void setError(EditText input, String error) {
        CharSequence current = input.getError();

        if (error == null) {
            if (current != null)
                input.setError(null);
        } else if (current == null || !error.contentEquals(current)) {
            input.setError(error);
        }
    }

    /** An input is valid if it contains a number between 1 and max (inclusive). */
    private static boolean isValidNumber(EditText input, int max) {
        int value = parseInput(input, -1, max);

        return value > 0;
    }

    /**
     * Safely parses the content of an input field, returning the fallback value if the input is
     * empty, not a number or out of the allowed range.
     */
    private static int parseInput(EditText input, int fallback, int max) {
        String value = input.getText().toString().trim();

        if (TextUtils.isEmpty(value))
            return fallback;

        try {
            int parsed = Integer.parseInt(value);

            if (parsed < 1 || parsed > max)
                return fallback;

            return parsed;
        } catch (NumberFormatException e) {
            return fallback;
        }
    }
}

